#!/usr/bin/env node
/**
 * Ensure packages/overlay-ui/src/build-info.generated.ts exists.
 *
 * The file is generated by scripts/local/build-info-watcher.sh during
 * local development, and gitignored. Fresh checkouts and CI have no
 * watcher, so the import in mount-overlay.ts would fail typecheck.
 * This script writes a one-shot stub from the current git SHA so any
 * typecheck/build can run unattended.
 *
 * Idempotent and safe to call before every typecheck/build.
 */

import { execSync } from 'node:child_process';
import { existsSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(__dirname, '..');
const target = join(repoRoot, 'packages', 'overlay-ui', 'src', 'build-info.generated.ts');

if (existsSync(target)) process.exit(0);

const sha = execSync('git rev-parse --short HEAD', { cwd: repoRoot, encoding: 'utf8' }).trim();
const time = new Date().toISOString().slice(0, 16).replace('T', ' ');

writeFileSync(
  target,
  `// Auto-generated stub written by scripts/ensure-build-info.mjs.\n` +
  `// Overwritten on every git HEAD change by scripts/local/build-info-watcher.sh\n` +
  `// during local development. Do not edit; gitignored.\n` +
  `export const BUILD_COMMIT = "${sha}";\n` +
  `export const BUILD_TIME = "${time}";\n`,
);
console.log(`[ensure-build-info] wrote ${target} (sha=${sha})`);
